+  /**
+   * The schema type.
+   */
+  readonly type: 'recur';
+}
+
+/**
+ * Recur placeholder.
+ */
+export const Recur: Recur = {
+  kind: 'schema',
+  type: 'recur',
+  reference: recursive,
+  expects: 'unknown',
+  async: false,
+  get '~standard'() {
+    return _getStandardProps(this);
+  },
+  '~run'() {
+    throw new Error('Recur must be wrapped with recursive.');
+  },
+};
+
+/**
+ * Creates a recursive schema.
+ *
+ * @param wrapped The schema containing recur placeholders.
+ *
+ * @returns A recursive schema.
+ */
+// @__NO_SIDE_EFFECTS__
+export function recursive<
+  const TWrapped extends BaseSchema<unknown, unknown, BaseIssue<unknown>>,
+>(wrapped: TWrapped): RecursiveSchema<TWrapped> {
+  let schema: RecursiveSchema<TWrapped>;
+  const [resolved] = _resolveRecur(wrapped, () => schema);
+  schema = {
+    kind: 'schema',
+    type: 'recursive',
+    reference: recursive,
+    expects: wrapped.expects,
+    async: false,
+    wrapped: resolved,
+    get '~standard'() {
+      return _getStandardProps(this);
+    },
+    '~run'(dataset, config) {
+      return this.wrapped['~run'](dataset, config);
+    },
+  } as RecursiveSchema<TWrapped>;
+  return schema;
+}
+
+/**
+ * Resolves recur placeholders in a value.
+ *
+ * @param value The value to resolve.
+ * @param getSchema The function to get recursive schema.
+ *
+ * @returns The resolved value and whether it contains a recur placeholder.
+ *
+ * @internal
+ */
+export function _resolveRecur<TValue>(
+  value: TValue,
+  getSchema: () => BaseSchema<unknown, unknown, BaseIssue<unknown>>
+): [TValue, boolean] {
+  if (value === Recur) {
+    return [getSchema() as TValue, true];
+  }
+  if (Array.isArray(value)) {
+    let containsRecur = false;
+    const resolved = value.map((item) => {
+      const [resolvedItem, itemContainsRecur] = _resolveRecur(item, getSchema);
+      containsRecur ||= itemContainsRecur;
+      return resolvedItem;
+    });
+    return [
+      (containsRecur ? resolved : value) as TValue,
+      containsRecur,
+    ];
+  }
+  if (value && typeof value === 'object') {
+    let containsRecur = false;
+    const descriptors = Object.getOwnPropertyDescriptors(value);
+    for (const key of Reflect.ownKeys(descriptors)) {
+      const descriptor = descriptors[key as keyof typeof descriptors];
+      if ('value' in descriptor && typeof descriptor.value !== 'function') {
+        const [resolvedValue, valueContainsRecur] = _resolveRecur(
+          descriptor.value,
+          getSchema
+        );
+        if (valueContainsRecur) {
+          descriptor.value = resolvedValue;
+          containsRecur = true;
+        }
+      }
+    }
+    if (containsRecur) {
+      return [
+        Object.create(Object.getPrototypeOf(value), descriptors) as TValue,
+        true,
+      ];
+    }
+  }
+  return [value, false];
+}
